#include<bits/stdc++.h>
using namespace std;using I=long long;using P=array<I,7>;using Key=array<I,3>;struct Rec{int ci,mask,l;uint32_t code;P p;};struct Hash{size_t operator()(Key k)const{uint64_t h=1469598103934665603ULL;for(auto x:k){h^=x;h*=1099511628211ULL;}return h;}};
P mv(P p,char c){auto[h,s,e,L,R,d,b]=p;if(c=='O')return{h,s,0,L,2*R,d,2*b};if(c=='Z')return{h+R-e,s,d,L+b,2*R-d,d,2*b};if(c=='P')return{h,0,e,2*L,R,d,2*b};return{h+L-s,d,e,2*L-d,R+b,d,2*b};}
int main(int argc,char**argv){int cap=argc>1?atoi(argv[1]):12;ifstream in("POWER_CORES_ROOTED.txt");int ci,mask;P p;vector<Rec>cores;while(in>>ci>>mask){for(auto&v:p)in>>v;cores.push_back({ci,mask,0,0,p});}long long states=0,hits=0,partial=0;ofstream control("CORE_COUNTERROTATION_DEFECTS.txt");
for(int N=0;N<=cap;N++){unordered_map<Key,Rec,Hash>bank;map<pair<I,I>,pair<I,I>>range;
for(int side=0;side<2;side++){int pad=N+(side==1?3:0);for(auto z:cores){if((z.p[5]==19)!=(side==0))continue;for(int l=0;l<=pad;l++){int r=pad-l;function<void(P,int,uint32_t)>right=[&](P p,int left,uint32_t code){if(left){if(left>1)right(mv(p,'O'),left-1,code<<1);right(mv(p,'Z'),left-1,(code<<1)|1);return;}states++;auto[h,s,e,L,R,d,b]=p;if(s!=d||e!=d)return;I a=L-d,rr=R-d,j=(d-d%3)/3;Key key{a,rr,h+2*j};if(side==0){bank.try_emplace(key,Rec{z.ci,z.mask,l,code,p});auto k=make_pair(a,rr);auto it=range.find(k);if(it==range.end())range[k]={h,h};else{it->second.first=min(it->second.first,h);it->second.second=max(it->second.second,h);}}else{auto rg=range.find({a,rr});if(rg!=range.end()){partial++;control<<N<<" "<<l<<" "<<z.mask<<" "<<code<<" "<<rg->second.first-h<<" "<<rg->second.second-h<<"\n";}auto it=bank.find(key);if(it!=bank.end()){hits++;cout<<"MATCH N "<<N<<"\n";for(auto t:{it->second,Rec{z.ci,z.mask,l,code,p}}){cout<<t.ci<<" "<<t.mask<<" "<<t.l<<" "<<t.code;for(auto v:t.p)cout<<" "<<v;cout<<"\n";}cout<<flush;}}};
function<void(P,int,uint32_t)>left=[&](P p,int rem,uint32_t code){if(rem){if(rem>1)left(mv(p,'P'),rem-1,code<<1);left(mv(p,'Q'),rem-1,(code<<1)|1);return;}right(p,r,code);};left(z.p,l,0);}}}
cerr<<"padding "<<N<<" states "<<states<<" keys "<<bank.size()<<" partial "<<partial<<" hits "<<hits<<"\n";if(hits)break;}
}
